2f1eff5 now support parsing Apple's Maker Note (#71)
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  57) exif_mnote_data_apple_load(ExifMnoteData *md, const unsigned char *buf, unsigned int buf_size) {
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  58)     ExifMnoteDataApple *d = (ExifMnoteDataApple *) md;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  59)     unsigned int tcount, i;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  60)     unsigned int dsize;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  61)     unsigned int ofs, dofs;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  62)
d0ebd6ea (Marcus Meissner 2021-08-14 15:25:13 +0200  63)     /*printf("%s\n", __FUNCTION__);*/
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  64)
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  65)     if (!d || !buf || (buf_size < 6 + 16)) {
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  66)         exif_log(md->log, EXIF_LOG_CODE_CORRUPT_DATA,
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  67)                  "ExifMnoteDataApple", "Short MakerNote");
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  68)         return;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  69)     }
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  70)
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  71)     /* Start of interesting data */
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  72)     ofs = d->offset + 6;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  73)
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  74)     if ((buf[ofs + 12] == 'M') && (buf[ofs + 13] == 'M')) {
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  75)         d->order = EXIF_BYTE_ORDER_MOTOROLA;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  76)     } else if ((buf[ofs + 12] == 'I') && (buf[ofs + 13] == 'I')) {
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  77)         d->order = EXIF_BYTE_ORDER_INTEL;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  78)     } else {
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  79)         exif_log(md->log, EXIF_LOG_CODE_CORRUPT_DATA,
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  80)                 "ExifMnoteDataApple", "Unrecognized byte order");
d0ebd6ea (Marcus Meissner 2021-08-14 15:25:13 +0200  81)         /*printf("%s(%d)\n", __FUNCTION__, __LINE__);*/
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  82)         return;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  83)     }
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  84)
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  85)     tcount = (unsigned int) exif_get_short(buf + ofs + 14, d->order);
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  86)
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  87)     /* Sanity check the offset */
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  88)     if (buf_size < 6 + 16 + tcount * 6 + 4) {
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  89)         exif_log(md->log, EXIF_LOG_CODE_CORRUPT_DATA,
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  90)                  "ExifMnoteDataApple", "Short MakerNote");
d0ebd6ea (Marcus Meissner 2021-08-14 15:25:13 +0200  91)         /*printf("%s(%d)\n", __FUNCTION__, __LINE__);*/
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  92)         return;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  93)     }
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  94)
d0ebd6ea (Marcus Meissner 2021-08-14 15:25:13 +0200  95)     /* printf("%s(%d): total %d tags\n", __FUNCTION__, __LINE__, tcount); */
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  96)
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  97)     ofs += 16;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  98)
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200  99)     exif_mnote_data_apple_free(md);
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 100)
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 101)     /* Reserve enough space for all the possible MakerNote tags */
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 102)     d->entries = exif_mem_alloc(md->mem, sizeof(MnoteAppleEntry) * tcount);
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 103)     if (!d->entries) {
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 104)         EXIF_LOG_NO_MEMORY(md->log, "ExifMnoteApple", sizeof(MnoteAppleEntry) * tcount);
d0ebd6ea (Marcus Meissner 2021-08-14 15:25:13 +0200 105)         /*printf("%s(%d)\n", __FUNCTION__, __LINE__);*/
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 106)         return;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 107)     }
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 108)
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 109)     for (i = 0; i < tcount; i++) {
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 110)         d->entries[i].tag = exif_get_short(buf + ofs, d->order);
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 111)         d->entries[i].format = exif_get_short(buf + ofs + 2, d->order);
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 112)         d->entries[i].components = exif_get_long(buf + ofs + 4, d->order);
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 113)         d->entries[i].order = d->order;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 114)         dsize = exif_format_get_size(d->entries[i].format) * d->entries[i].components;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 115)         if (dsize > 4) {
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 116)             dofs = d->offset + exif_get_long(buf + ofs + 8, d->order);
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 117)         } else {
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 118)             dofs = ofs + 8;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 119)         }
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 120)         ofs += 12;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 121)         d->entries[i].data = exif_mem_alloc(md->mem, dsize);
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 122)         if (!d->entries[i].data) {
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 123)             EXIF_LOG_NO_MEMORY(md->log, "ExifMnoteApple", dsize);
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 124)             continue;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 125)         }
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 126)         memcpy(d->entries[i].data, buf + dofs, dsize);
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 127)         d->entries[i].size = dsize;
2f1eff50 (Marcus Meissner 2021-08-14 14:22:19 +0200 128)     }
